NativeBoneChain::NativeBoneChain(NativeSceneNode& host,NativeSceneNode& root,Parameter settings,std::vector<NativeDynamicCollider> colliders,std::optional<std::vector<NativeSceneRenderer*>> visibility,const std::unordered_map<NativeSceneNode*,Matrix4x4>* transforms,const std::unordered_map<NativeSceneNode*,Quaternion>* rotations):host_(&host),root_(&root),settings_(std::move(settings)),colliders_(std::move(colliders)),visibility_(std::move(visibility)),setupTransforms_(transforms),setupRotations_(rotations){for(auto& p:settings_.Get("m_Exclusions").Children)exclusions_.insert(p.Text);for(auto& p:settings_.Get("m_notRolls").Children)notRolls_.insert(p.Text);gravity_=Vector(settings_.Get("m_Gravity"));force_=Vector(settings_.Get("m_Force"));localGravity_=Rotate(Inverse(SetupRotation(root_)),gravity_);previousHost_=host_->Position();Add(root_,-1,0);for(auto& p:particles_){float t=totalLength_>0?p.Distance/totalLength_:0;p.Damping=Value("Damping",t);p.Elasticity=Value("Elasticity",t);p.Stiffness=Value("Stiffness",t);p.Inert=Value("Inert",t);p.Radius=Value("Radius",t,false);}setupTransforms_=nullptr;setupRotations_=nullptr;}
float NativeBoneChain::Value(const std::string& name,float t,bool clamp)const{float value=settings_.Float("m_"+name);auto& data=settings_.Get("m_"+name+"Distrib");if(!data.Get("m_Curve").Children.empty()){std::vector<CurveKey> keys;for(auto& k:data.Get("m_Curve").Children)keys.push_back({k.Float("time"),k.Float("value"),k.Float("inSlope"),k.Float("outSlope"),k.Float("inWeight",1.f/3),k.Float("outWeight",1.f/3),static_cast<int>(k.Int("weightedMode"))});AnimationCurve curve(std::move(keys));auto wrap=[](int v){return v==4?CurveWrap::Loop:v==5?CurveWrap::PingPong:CurveWrap::Clamp;};curve.Pre=wrap(static_cast<int>(data.Int("m_PreInfinity",2)));curve.Post=wrap(static_cast<int>(data.Int("m_PostInfinity",2)));value*=curve.Evaluate(t);}return clamp?std::clamp(value,0.f,1.f):std::max(0.f,value);}
Matrix4x4 NativeBoneChain::SetupMatrix(NativeSceneNode* node)const{return setupTransforms_&&setupTransforms_->contains(node)?setupTransforms_->at(node):node->WorldMatrix();}
Quaternion NativeBoneChain::SetupRotation(NativeSceneNode* node)const{return setupRotations_&&setupRotations_->contains(node)?setupRotations_->at(node):node->Rotation();}
Vector3 NativeBoneChain::SetupPosition(NativeSceneNode* node)const{return hs2::TransformPoint({},SetupMatrix(node));}
void NativeBoneChain::Add(NativeSceneNode* bone,int parent,float distance){Require(particles_.size()<20000,"Dynamic bone hierarchy exceeds limit.");Particle p;p.Bone=bone;p.Parent=parent;if(bone){p.Position=bone->Position();p.RestPosition=bone->LocalPosition();p.RestRotation=bone->LocalRotation();}else{auto* node=particles_[parent].Bone;float length=settings_.Float("m_EndLength");p.End=length>0?(node->Parent()?hs2::TransformPoint(SetupPosition(node)*2-SetupPosition(node->Parent()),InverseMatrix(SetupMatrix(node)))*length:Vector3{length,0,0}):hs2::TransformVector(Rotate(SetupRotation(host_),Vector(settings_.Get("m_EndOffset"))),InverseMatrix(SetupMatrix(node)));p.Position=node->TransformPoint(p.End);}p.Previous=p.Position;p.SetupPosition=bone?SetupPosition(bone):hs2::TransformPoint(p.End,SetupMatrix(particles_[parent].Bone));if(parent>=0)distance+=Length(particles_[parent].SetupPosition-p.SetupPosition);p.Distance=distance;totalLength_=std::max(totalLength_,distance);int index=static_cast<int>(particles_.size());particles_.push_back(p);if(!bone)return;bool end=settings_.Float("m_EndLength")>0||LengthSquared(Vector(settings_.Get("m_EndOffset")))!=0;NativeSceneNode* bypass=nullptr;for(auto* child:bone->Children()){bool excluded=exclusions_.contains(child->Name);if(!excluded&&notRolls_.contains(child->Name)){bypass=child;excluded=true;}if(!excluded)Add(child,index,distance);else if(end)Add(nullptr,index,distance);}if(bypass)for(auto* child:bypass->Children())if(!exclusions_.contains(child->Name)&&!notRolls_.contains(child->Name))Add(child,index,distance);if(bone->Children().empty()&&end)Add(nullptr,index,distance);}
void NativeBoneChain::Restore(){if(visibility_&&!visible_)return;for(auto& p:particles_)if(p.Bone){p.Bone->LocalPosition(p.RestPosition);p.Bone->LocalRotation(p.RestRotation);}}
void NativeBoneChain::Reset(){for(auto& p:particles_)p.Previous=p.Position=p.Bone?p.Bone->Position():particles_[p.Parent].Bone->TransformPoint(p.End);previousHost_=host_->Position();}
void NativeBoneChain::RefreshBoundOrientation(){localGravity_=Rotate(Inverse(root_->Rotation()),gravity_);for(auto& p:particles_)if(!p.Bone){auto* node=particles_[p.Parent].Bone;float length=settings_.Float("m_EndLength");p.End=length>0?(node->Parent()?node->InverseTransformPoint(node->Position()*2-node->Parent()->Position())*length:Vector3{length,0,0}):node->InverseTransformPoint(host_->TransformDirection(Vector(settings_.Get("m_EndOffset")))+node->Position());}Reset();}
void NativeBoneChain::RefreshGravityOrientation(){localGravity_=root_->InverseTransformDirection(gravity_);}
void NativeBoneChain::UpdateVisibility(){if(!visibility_)return;bool next=std::any_of(visibility_->begin(),visibility_->end(),[](auto* r){return r&&r->LastRenderedVisibility.value_or(r->Visible());});if(next&&!visible_){Reset();justEnabled_=true;}visible_=next;}
