    for(size_t i=1;i<particles_.size();++i){auto& p=particles_[i];auto& parent=particles_[p.Parent];auto target=hs2::TransformPoint(p.Local,Translation(parent.Matrix,parent.Position));p.Position+=(target-p.Position)*p.Elasticity;auto displacement=target-p.Position;float deviation=Length(displacement),maximum=static_cast<float>(p.Length*(1-static_cast<double>(p.Stiffness))*2);if(p.Stiffness>0&&deviation>maximum)p.Position+=displacement*static_cast<float>((static_cast<double>(deviation)-maximum)/deviation);for(auto& collider:colliders_)collider.Constrain(p.Position,p.Radius*scale,true);auto direction=parent.Position-p.Position;float length=Length(direction);if(length>0)p.Position+=direction*static_cast<float>((static_cast<double>(length)-p.Length)/length);}
