void NativeBodyDynamics::Restore(){for(auto& node:nodes_)if(node.Bone){node.Bone->LocalPosition(node.Reference->LocalPosition());node.Bone->LocalRotation(node.Reference->LocalRotation());node.Bone->LocalScale(node.Reference->LocalScale());}}
void NativeBodyDynamics::Reset(){for(size_t i=0;i<nodes_.size();++i){auto& node=nodes_[i];node.Previous=node.Position=node.Bone?node.Bone->Position():nodes_[i-1].Bone->TransformPoint(node.Local);}previousRoot_=root_->Position();accumulator_=0;}
